package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class AssetRelationshipsBrowserAcceptance {
    static void run(BrowserTest h)throws Exception{
        String base,target,query="BrowserChoice"+id(),title=query+" Desired <script>";try(var db=h.store.open()){PlatformFoundationTest.bind(db);base=AssetRelationshipsAcceptance.asset(db,"Relationship browser source");for(int i=0;i<25;i++)AssetRelationshipsAcceptance.asset(db,query+" option "+i);target=AssetRelationshipsAcceptance.asset(db,title);db.connection.commit();}
        try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
            var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/record/cmdb_ci/"+base);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review direct relationships")).press("Enter");assertThat(page.locator("main")).containsText("0 visible direct relationships");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Add a dependency")).press("Enter");page.getByLabel("Search configuration items").fill(query);page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Find items")).click();assertThat(page.locator("main")).containsText("26 visible search matches");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Next items")).press("Enter");assertThat(page.locator("main")).containsText(title);assertThat(page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Previous items"))).isVisible();
            for(String theme:new String[]{"light","dark"}){if(theme.equals("dark")){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(390,844);}ReleaseBrowserAcceptance.checkAccessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/asset-relationship-choose-"+theme+".png")).setFullPage(true));}
            page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Add relationship with "+title)).press("Enter");assertThat(page.locator("main")).containsText("1 visible direct relationship");assertThat(page.locator("main")).containsText(title);assertEquals(0,page.locator("main script").count());ReleaseBrowserAcceptance.checkAccessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/asset-relationships-dark.png")).setFullPage(true));page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(1280,720);ReleaseBrowserAcceptance.checkAccessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/asset-relationships-light.png")).setFullPage(true));
            page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName(title).setExact(true)).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Inspect dependent configuration items")).press("Enter");assertThat(page.locator("main")).containsText("Relationship browser source");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review direct relationships")).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("View dependents")).press("Enter");assertThat(page.locator("main")).containsText("Relationship browser source");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Remove relationship with Relationship browser source")).press("Enter");assertThat(page.locator("main")).containsText("0 visible direct relationships");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review dependency impact")).press("Enter");assertThat(page.locator("main")).containsText("No visible dependent records");
        }
    }
}
